#include "Zancle/Trait/RemoveReference.hpp"


////////////////////////////////////////////////////////////
/// \brief Casts its argument to an rvalue reference
///
////////////////////////////////////////////////////////////
#define ZA_MOVE(...) static_cast<ZA_REMOVE_REFERENCE(decltype(__VA_ARGS__)) &&>(__VA_ARGS__)


////////////////////////////////////////////////////////////
/// \brief Forwards its argument, preserving its value category
///
////////////////////////////////////////////////////////////
#define ZA_FORWARD(...) static_cast<decltype(__VA_ARGS__)&&>(__VA_ARGS__)
